func runDurationSeconds(run matrixRunReport) float64 {
	if run.WallSeconds != nil {
		return *run.WallSeconds
	}
	if !run.StartedAt.IsZero() && !run.FinishedAt.IsZero() {
		return run.FinishedAt.Sub(run.StartedAt).Seconds()
	}
	return 0
}

